/**
 * Types for the OpenNext worker bundle (`.open-next/worker.js`, generated by
 * `opennextjs-cloudflare build`). worker.ts imports it as "open-next-worker" (tsconfig paths);
 * the Next.js server bundle ("open-next-server") and OpenNext's request context ("open-next-init")
 * are used to load the server at isolate startup.
 */
declare module "open-next-server" {}
declare module "open-next-init" {
  export function runWithCloudflareRequestContext<T>(
    request: Request,
    env: object,
    ctx: ExecutionContext,
    handler: () => Promise<T>,
  ): Promise<T>;
}

declare module "open-next-worker" {
  const handler: {
    fetch: (request: Request, env: object, ctx: ExecutionContext) => Promise<Response>;
  };
  export default handler;
  export class DOQueueHandler {}
  export class DOShardedTagCache {}
  export class BucketCachePurge {}
}
